# Validate the APT repository structure with apt-ftparchive # This script checks the repository structure and generates the necessary metadata files. # It should be run from the root of the APT repository (soryos-apt). # # Steps: #   1. Create the dists directory structure for the distribution (e.g., stable) #   2. Generate Packages and Release files using apt-ftparchive #   3. Optionally sign the Release file # # Usage: #   ./validate-repository.sh [distribution] [component] #   # Example: ./validate-repository.sh stable main #   # If no arguments, defaults to distribution='stable' and component='main' set -euo pipefail DISTRIBUTION=${1:-stable} COMPONENT=${2:-main} REPO_DIR=$(pwd) DISTS_DIR=${REPO_DIR}/dists/${DISTRIBUTION} POOL_DIR=${REPO_DIR}/pool # Create the directory structure for the distribution mkdir -p ${DISTS_DIR}/${COMPONENT}/{binary-amd64,source} # Generate the Packages file for binary packages echo 